import {addVendor,updateCoverage} from "@/app/actions";import {AppShell} from "@/components/app-shell";import {Badge,buttonClass,Card,Drawer,Eyebrow,Field,inputClass,PageHeader} from "@/components/card";import {formatCents} from "@/lib/format";import {prisma} from "@/lib/prisma";import {getAmericanCelebration} from "@/lib/wedding";
export const dynamic="force-dynamic";
export default async function VendorsPage(){const {wedding,celebration}=await getAmericanCelebration();const [vendors,coverage]=await Promise.all([prisma.vendor.findMany({where:{weddingId:wedding.id},orderBy:[{category:"asc"},{name:"asc"}]}),prisma.coverageItem.findMany({where:{celebrationId:celebration.id},orderBy:{service:"asc"}})]);const categories=Array.from(new Set(vendors.map(v=>v.category)));const form=<form action={addVendor} className="grid gap-4"><Field label="Vendor name"><input className={inputClass} name="name" required/></Field><div className="grid grid-cols-2 gap-3"><Field label="Service"><input className={inputClass} name="category" required/></Field><Field label="Status"><select className={inputClass} name="status"><option value="researching">Researching</option><option value="contacted">Contacted</option><option value="quoted">Quoted</option><option value="shortlisted">Shortlisted</option><option value="booked">Booked</option></select></Field></div><Field label="Quote"><input className={inputClass} name="quote" type="number" step=".01"/></Field><Field label="Contact name"><input className={inputClass} name="contactName"/></Field><Field label="Email"><input className={inputClass} name="email" type="email"/></Field><Field label="Phone"><input className={inputClass} name="phone"/></Field><Field label="Website"><input className={inputClass} name="website" type="url"/></Field><Field label="Notes"><textarea className={inputClass} name="notes" rows={4}/></Field><button className={buttonClass}>Add vendor</button></form>;return <AppShell><PageHeader eyebrow="Vendors & services" title="Service board" description="Your venue handles the foundation. This board makes every outside decision visible." action={<Drawer label="+ Add vendor" title="Add a vendor">{form}</Drawer>}/><section className="grid gap-4 sm:grid-cols-3"><Card><p className="text-xs text-mist">Services tracked</p><p className="stat-value">{categories.length}</p></Card><Card><p className="text-xs text-mist">Booked</p><p className="stat-value">{vendors.filter(v=>v.status==="booked").length}</p></Card><Card><p className="text-xs text-mist">Need a decision</p><p className="stat-value">{coverage.filter(c=>c.ownedBy==="tbd").length}</p></Card></section><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{categories.map(cat=>{const list=vendors.filter(v=>v.category===cat),booked=list.find(v=>v.status==="booked");return <Card key={cat} className="flex min-h-64 flex-col"><div className="flex items-start justify-between"><div><Eyebrow>{cat.replaceAll("_"," ")}</Eyebrow><h3 className="mt-2 font-display text-2xl font-semibold">{booked?booked.name:`${list.length} options`}</h3></div><Badge tone={booked?"sage":"gold"}>{booked?"Booked":"In progress"}</Badge></div>{booked?<div className="mt-5 rounded-xl bg-sage-light p-4"><p className="text-xs text-mist">Committed quote</p><p className="mt-1 font-display text-3xl font-semibold">{formatCents(booked.quoteCents)}</p><p className="mt-2 text-xs text-mist">{booked.contactName??booked.email??"Contact details to add"}</p></div>:<div className="mt-5 space-y-2">{list.map(v=><div className="flex justify-between rounded-xl bg-linen px-3 py-3" key={v.id}><div><p className="text-sm font-semibold">{v.name}</p><p className="text-xs capitalize text-mist">{v.status}</p></div><p className="text-xs font-semibold">{formatCents(v.quoteCents)}</p></div>)}</div>}<p className="mt-auto pt-5 text-xs font-semibold text-sage-dark">{booked?"View booking →":"Compare options →"}</p></Card>})}{categories.length===0&&<Card className="md:col-span-2 xl:col-span-3"><p className="py-8 text-center text-sm text-mist">Add the outside services you want to compare.</p></Card>}</div><Card><div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><Eyebrow>Venue package</Eyebrow><h3 className="mt-1 font-display text-3xl font-semibold">Coverage, without another page</h3></div><p className="text-xs text-mist">Change an owner and save inline</p></div><div className="mt-5 grid gap-3 md:grid-cols-2">{coverage.map(c=><form action={updateCoverage} className="rounded-xl border border-line p-4" key={c.id}><input type="hidden" name="coverageId" value={c.id}/><div className="flex items-center justify-between gap-3"><p className="text-sm font-semibold capitalize">{c.service.replaceAll("_"," ")}</p><Badge tone={c.ownedBy==="venue_package"?"sage":c.ownedBy==="tbd"?"gold":"blush"}>{c.ownedBy.replaceAll("_"," ")}</Badge></div><div className="mt-3 flex gap-2"><select className={inputClass} name="ownedBy" defaultValue={c.ownedBy}><option value="venue_package">Venue package</option><option value="outside_vendor">Outside vendor</option><option value="diy">Self managed</option><option value="not_needed">Not needed</option><option value="tbd">Undecided</option></select><input type="hidden" name="notes" value={c.notes??""}/><button className="rounded-xl bg-ink px-3 text-xs font-bold text-white">Save</button></div></form>)}</div></Card></AppShell>}
